    /**
     * Get cached language data from reflection.
     *
     * @return array<string, array{type: string, description: string, added: string, scope: ?string, comments: ?string, macrolanguage: ?string, deprecated: ?string, preferredvalue: ?string, suppressscript: ?string}>
     */
    private static function languageData(): array
    {
        // Define arrow function to extract language data from attribute info
        $dataExtractor = fn ($info, $caseValue) => [
            'type' => $info->type,
            'description' => $info->description,
            'added' => $info->added,
            'scope' => $info->scope,
            'comments' => $info->comments,
            'macrolanguage' => $info->macrolanguage,
            'deprecated' => $info->deprecated,
            'preferredvalue' => $info->preferredvalue,
            'suppressscript' => $info->suppressscript,
        ];

        // Build lazy data map from enum cases and their attributes
        $result = EnumDataUtils::buildLazyDataMap(
            self::class,
            LanguageBCP47Info::class,
            $dataExtractor
        );

        // Clean up variables to free up memory
        unset(
            $dataExtractor
        );

        // Return cached language data map
        return $result;
    }

    /**
     * Get the type of the language tag.
     *
     * @return string The type of the language tag
     */
    public function type(): string
    {
        // Get cached language data from reflection
        $data = self::languageData();

        // Return type field value with default fallback
        return EnumDataUtils::getFieldValue(
            $data,
            $this->value,
            'type',
            'language'
        );
    }

